class SavedVbaTests {
 static byte[] Literal(byte[] data){using(var output=new MemoryStream()){output.WriteByte(1);for(int offset=0;offset<data.Length;offset+=3500){using(var chunk=new MemoryStream()){int end=Math.Min(offset+3500,data.Length);for(int p=offset;p<end;){chunk.WriteByte(0);int length=Math.Min(8,end-p);chunk.Write(data,p,length);p+=length;}int header=0xB000|((int)chunk.Length-1);output.WriteByte((byte)header);output.WriteByte((byte)(header>>8));chunk.Position=0;chunk.CopyTo(output);}}return output.ToArray();}}
 static void Write(SavedVbaReader.IStorage storage,string name,byte[] value){IStream stream=null;try{storage.OpenStream(name,IntPtr.Zero,0x12,0,out stream);stream.SetSize(value.Length);stream.Seek(0,0,IntPtr.Zero);stream.Write(value,value.Length,IntPtr.Zero);stream.Commit(0);}finally{if(stream!=null)Marshal.ReleaseComObject(stream);}}
 static byte[] Read(SavedVbaReader.IStorage storage,string name){IStream stream=null;try{storage.OpenStream(name,IntPtr.Zero,0x12,0,out stream);System.Runtime.InteropServices.ComTypes.STATSTG stat;stream.Stat(out stat,1);byte[] data=new byte[(int)stat.cbSize];stream.Read(data,data.Length,IntPtr.Zero);return data;}finally{if(stream!=null)Marshal.ReleaseComObject(stream);}}
 static string Protect(string hex){byte seed=Convert.ToByte(hex.Substring(0,2),16),version=Convert.ToByte(hex.Substring(2,2),16),key=Convert.ToByte(hex.Substring(4,2),16);var result=new List<byte>{seed,version,key};int previous=version,last=key,lastPlain=seed^key;var plain=new List<byte>();for(int i=0;i<(seed&6)/2;i++)plain.Add(0);plain.AddRange(BitConverter.GetBytes(4));plain.AddRange(BitConverter.GetBytes(1));foreach(byte b in plain){byte encrypted=(byte)(b^((previous+lastPlain)&255));result.Add(encrypted);previous=last;last=encrypted;lastPlain=b;}return BitConverter.ToString(result.ToArray()).Replace("-","");}
 static void Package(string bin,string zip){if(File.Exists(zip))File.Delete(zip);using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create))archive.CreateEntryFromFile(bin,"xl/vbaProject.bin");}
 static void StaticReferences(string fixture,string zip,List<VbaModuleSource> modules){string changed=Path.GetFullPath("vsto/tests/fixtures/static-references-vbaProject.bin");File.Copy(fixture,changed,true);SavedVbaReader.IStorage root=null,vba=null;try{Marshal.ThrowExceptionForHR(SavedVbaReader.StgOpenStorage(changed,null,0x12,IntPtr.Zero,0,out root));root.OpenStorage("VBA",null,0x12,IntPtr.Zero,0,out vba);var module=modules.Single(m=>m.Name=="Module1");byte[] original=Read(vba,module.StreamName);string code="Attribute VB_Name = \"Module1\"\r\nSub CheckRefs()\r\nDim x\r\nx = Worksheets(\"Input\").Range(\"B5\").Value\r\nWorksheets(\"Input\").Cells(5, 2).Value = 7\r\nWorksheets(\"Input\").Range(\"A1:C10\").ClearContents\r\nEnd Sub\r\n";byte[] compressed=Literal(Encoding.GetEncoding(1252).GetBytes(code));var updated=new byte[module.SourceOffset+compressed.Length];Buffer.BlockCopy(original,0,updated,0,module.SourceOffset);Buffer.BlockCopy(compressed,0,updated,module.SourceOffset,compressed.Length);Write(vba,module.StreamName,updated);vba.Commit(0);root.Commit(0);}finally{if(vba!=null)Marshal.ReleaseComObject(vba);if(root!=null)Marshal.ReleaseComObject(root);}Package(changed,zip);byte[] before=File.ReadAllBytes(zip);var extracted=SavedVbaReader.Read(zip,CancellationToken.None);var edges=extracted.SelectMany(m=>VbaParser.Parse(m.Code,"fixture.xlsm",m.Name,null)).ToList();if(edges.Count!=3||!edges.Any(e=>e.Kind=="vbaRead")||!edges.Any(e=>e.Kind=="vbaWrite")||!edges.Any(e=>e.Kind=="vbaRange"))throw new Exception("Saved static reference extraction");if(!before.SequenceEqual(File.ReadAllBytes(zip)))throw new Exception("Reader modified source");Console.WriteLine("PASS saved-file VBA read/write/range operations; source unchanged");string protectedBin=changed+".protected";File.Copy(changed,protectedBin,true);root=null;try{Marshal.ThrowExceptionForHR(SavedVbaReader.StgOpenStorage(protectedBin,null,0x12,IntPtr.Zero,0,out root));string project=Encoding.GetEncoding(1252).GetString(Read(root,"PROJECT"));project=Regex.Replace(project,"(?m)^CMG=\"([0-9A-Fa-f]+)\"",m=>"CMG=\""+Protect(m.Groups[1].Value)+"\"");Write(root,"PROJECT",Encoding.GetEncoding(1252).GetBytes(project));root.Commit(0);}finally{if(root!=null)Marshal.ReleaseComObject(root);}string protectedZip=Path.GetFullPath("vsto/tests/fixtures/protected-vba-sample.xlsm");Package(protectedBin,protectedZip);bool refused=false;try{SavedVbaReader.Read(protectedZip,CancellationToken.None);}catch(UnauthorizedAccessException){refused=true;}if(!refused)throw new Exception("Protected project accepted");Console.WriteLine("PASS protected project refused before module extraction");}
 [STAThread]static int Main(){try{var state=SavedVbaReader.DecodeState("0705D8E3D8EDDBF1DBF1DBF1DBF1");if(state.Length!=4||BitConverter.ToUInt32(state,0)!=0)throw new Exception("Protection-state decode");Console.WriteLine("PASS official unprotected-state vector");string fixture=Path.GetFullPath("vsto/tests/fixtures/xlsxwriter-vbaProject.bin"),zip=Path.GetFullPath("vsto/tests/fixtures/saved-vba-sample.xlsm");if(File.Exists(zip))File.Delete(zip);using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create))archive.CreateEntryFromFile(fixture,"xl/vbaProject.bin");var modules=SavedVbaReader.Read(zip,CancellationToken.None);if(modules.Count<2||modules.All(m=>String.IsNullOrEmpty(m.Code)))throw new Exception("Module extraction");foreach(var module in modules)Console.WriteLine("MODULE "+module.Name+" lines="+module.Code.Split('\n').Length+" references="+VbaParser.Parse(module.Code,"fixture.xlsm",module.Name,null).Count);Console.WriteLine("PASS read actual Excel-generated VBA project without VBProject access");bool invalid=false;try{SavedVbaReader.Decompress(new byte[]{1,0,0},0,CancellationToken.None);}catch(InvalidDataException){invalid=true;}if(!invalid)throw new Exception("Malformed compression accepted");Console.WriteLine("PASS malformed compressed data rejected");StaticReferences(fixture,zip,modules);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
